function validate([matrix]) {
  if (!Array.isArray(matrix) || matrix.length < 1 || matrix.length > 300) return 'matrix needs 1 to 300 rows.';
  const cols = matrix[0].length;
  if (cols < 1 || cols > 300) return 'Each row needs 1 to 300 cells.';
  for (const row of matrix) {
    if (row.length !== cols) return 'All rows must have the same length.';
    if (row.some(v => v !== 0 && v !== 1)) return 'Every cell must be 0 or 1.';
  }
  return null;
}

