function countSquares(matrix) {
  const m = matrix.length;
  const n = matrix[0].length;
  let count = 0;
  for (let top = 0; top < m; top++) {
    for (let lft = 0; lft < n; lft++) {
      for (let side = 1; top + side <= m && lft + side <= n; side++) {
        let allOnes = true;
        for (let i = top; i < top + side && allOnes; i++) {
          for (let j = lft; j < lft + side; j++) {
            if (matrix[i][j] !== 1) { allOnes = false; break; }
          }
        }
        if (allOnes) count++;
      }
    }
  }
  return count;
}

