function generate(rand, size) {
  let rows, cols, density;
  if (size === 'large') {
    rows = 60 + Math.floor(rand() * 41);
    cols = 60 + Math.floor(rand() * 41);
    const mode = rand();
    density = mode < 0.25 ? 1 : mode < 0.5 ? 0.97 : 0.6 + rand() * 0.35;
  } else {
    rows = 1 + Math.floor(rand() * 5);
    cols = 1 + Math.floor(rand() * 5);
    const mode = rand();
    density = mode < 0.1 ? 0 : mode < 0.2 ? 1 : 0.4 + rand() * 0.55;
  }
  const matrix = Array.from({ length: rows }, () => Array.from({ length: cols }, () => (rand() < density ? 1 : 0)));
  return [matrix];
}
